package com.bank.jwt;

import javax.crypto.Mac;
import javax.crypto.spec.SecretKeySpec;
import java.nio.charset.StandardCharsets;
import java.util.Base64;
import java.util.logging.*;

public class JwtStructureDemo {
    private static final Logger log = Logger.getLogger(JwtStructureDemo.class.getName());
    static final String BANK_NAME = "National Bank of India";

    static {
        Logger root = Logger.getLogger("");
        for (Handler h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler ch = new ConsoleHandler();
        ch.setFormatter(new BankLogFormatter());
        ch.setLevel(Level.ALL);
        root.addHandler(ch);
        root.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        JwtCodec codec = new JwtCodec("national-bank-signing-secret-256-bit");

        String header = "{\"alg\":\"HS256\",\"typ\":\"JWT\"}";
        String payload = "{\"sub\":\"rajesh\",\"role\":\"CUSTOMER\",\"iss\":\"national-bank\",\"exp\":1730000900}";
        String jwt = codec.create(header, payload);
        log.info(() -> "JWT = " + jwt);

        String[] parts = jwt.split("\\.");
        log.info(() -> "Header  (segment 1) = " + codec.decode(parts[0]));
        log.info(() -> "Payload (segment 2) = " + codec.decode(parts[1]));
        log.info(() -> "Signature (segment 3) is opaque: " + parts[2]);

        // ANYONE can read the payload — proof it is NOT encrypted.
        log.warning("Payload is only Base64-decoded, readable by anyone -> never put secrets here");

        log.info(() -> "Signature valid? " + codec.verify(jwt));

        // Tamper: change role to ADMIN in the payload and re-encode.
        String evilPayload = payload.replace("CUSTOMER", "ADMIN");
        String evilP64 = Base64.getUrlEncoder().withoutPadding()
            .encodeToString(evilPayload.getBytes(StandardCharsets.UTF_8));
        String tampered = parts[0] + "." + evilP64 + "." + parts[2]; // old signature
        log.severe("Tampered token signature valid? " + codec.verify(tampered));
    }
}

